def compute(vars):
    expected_return = vars["v1"]
    expected_return_rate = vars["v2"] / 100.0

    if expected_return_rate == 0:
        return None

    plan_assets = expected_return / expected_return_rate

    return {
        "value": plan_assets,
        "trace": {
            "expected_return": expected_return,
            "expected_return_rate_decimal": expected_return_rate,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
